import{_ as r,c as n,o as e,ag as l}from"./chunks/framework.B-XtCDNB.js";const h=JSON.parse('{"title":"网络层（Internet Layer）","description":"","frontmatter":{},"headers":[],"relativePath":"network/internet-layer.md","filePath":"network/internet-layer.md","lastUpdated":1742369006000}'),o={name:"network/internet-layer.md"};function a(i,t,s,g,d,u){return e(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="网络层-internet-layer" tabindex="-1">网络层（Internet Layer） <a class="header-anchor" href="#网络层-internet-layer" aria-label="Permalink to &quot;网络层（Internet Layer）&quot;">​</a></h1><p>网络层负责为数据包选择合适的路径，并进行路由和转发，实现跨网络的数据传输。它使用 IP 协议来标识主机和路由器，并提供了数据包的传送服务。</p><h2 id="网络层的主要功能" tabindex="-1">网络层的主要功能 <a class="header-anchor" href="#网络层的主要功能" aria-label="Permalink to &quot;网络层的主要功能&quot;">​</a></h2><p>网络层主要负责数据包从源主机到目的主机的传输与转发，其核心功能包括：</p><ul><li><strong>路径选择（路由选择）：</strong><br> 根据网络拓扑和路由算法，选择最优路径将数据包从源地址转发到目的地址。</li><li><strong>数据包转发：</strong><br> 每个经过网络层的路由器根据目标 IP 地址查找路由表，将数据包转发到下一跳设备。</li><li><strong>逻辑地址管理：</strong><br> 提供 IP 地址（逻辑地址）的分配和管理，解决不同网络之间的互联问题。</li><li><strong>分段与重组：</strong><br> 当数据包过大时，网络层可能会对其进行分段处理；接收端则负责将这些分段数据重组为原始数据。</li></ul><h2 id="ip-协议" tabindex="-1">IP 协议 <a class="header-anchor" href="#ip-协议" aria-label="Permalink to &quot;IP 协议&quot;">​</a></h2><p><strong>IP 协议（Internet Protocol）</strong>：是网络层的核心协议，主要任务是将数据包从源主机传送到目的主机。</p><p><strong>无连接传输：</strong><br> IP 协议在传输数据时不建立专门的连接，也不维持状态信息。每个数据包（数据报）都独立传输，采用“尽力而为”的方式，不保证数据包必达、顺序正确或不重复。</p><p><strong>优缺点：</strong></p><ul><li><strong>优点：</strong> 实现简单、开销低，适合大规模互联；</li><li><strong>缺点：</strong> 不提供传输层面的可靠性，需由上层协议（如 TCP）补充可靠性保障。</li></ul><h2 id="子网掩码" tabindex="-1">子网掩码 <a class="header-anchor" href="#子网掩码" aria-label="Permalink to &quot;子网掩码&quot;">​</a></h2><p><strong>子网掩码</strong>：是一个 32 位的二进制数，用于区分 IP 地址中的网络部分和主机部分。</p><ul><li><strong>划分方法：</strong><ul><li>子网掩码中连续的 1 表示网络部分，后面的 0 表示主机部分。</li><li>例如：子网掩码 255.255.255.0（即二进制 11111111.11111111.11111111.00000000）表示前 24 位为网络号，后 8 位为主机号。</li></ul></li><li><strong>作用：</strong><br> 通过与 IP 地址按位与运算，可以得到网络地址，从而确定数据包所属的网络，便于路由器进行查找和转发。</li></ul><h2 id="icmp-协议" tabindex="-1">ICMP 协议 <a class="header-anchor" href="#icmp-协议" aria-label="Permalink to &quot;ICMP 协议&quot;">​</a></h2><p><strong>ICMP 协议（Internet Control Message Protocol）</strong>：是用于在网络设备间传递控制信息和错误报告的协议，属于网络层的一部分。</p><ul><li><strong>主要作用：</strong><ul><li><strong>错误报告：</strong> 如目的不可达（Destination Unreachable）、时间超过（Time Exceeded）等信息，帮助诊断网络故障。</li><li><strong>网络诊断：</strong> 例如使用 ICMP 的回显请求/应答（ping 命令）来检测目标主机是否可达，以及网络延时情况。</li></ul></li><li><strong>示例：</strong><br> 当路由器在转发数据包时发现目标主机不可达，它会发送一个 ICMP 错误消息通知源主机，从而帮助上层应用或网络管理员及时发现并处理网络问题。</li></ul><h2 id="nat-网络地址转换" tabindex="-1">NAT（网络地址转换） <a class="header-anchor" href="#nat-网络地址转换" aria-label="Permalink to &quot;NAT（网络地址转换）&quot;">​</a></h2><p>NAT（Network Address Translation）是一种将私有网络内部的 IP 地址转换为公共 IP 地址（以及反向转换）的技术。</p><ul><li><strong>工作原理：</strong><ul><li><strong>地址映射：</strong> 内部主机发送的数据包经过 NAT 设备时，其源 IP 地址会被替换为公共 IP 地址，同时记录映射关系；当外部数据包返回时，根据记录的映射关系，将目标地址还原成内部主机的 IP 地址。</li></ul></li><li><strong>作用：</strong><ul><li><strong>节省公共 IP 资源：</strong> 多个内部主机可以共享一个公共 IP 地址；</li><li><strong>提高安全性：</strong> 内部网络结构对外部隐藏，降低直接攻击风险；</li><li><strong>简化网络管理：</strong> 使内部网络可以自由规划，而无需受公共 IP 地址限制。</li></ul></li></ul>',19)])])}const p=r(o,[["render",a]]);export{h as __pageData,p as default};
